-- 01-install.sql — registry migrations and imported sources (all left UNREVIEWED; nothing is shown to users)
-- Generated by scripts/build-install-sql.js. Safe to run more than once.
-- Contains only public publication text and metadata; no secrets.

-- ===== supabase/migrations/004_reference_registry.sql =====
-- Versioned source registry + rank-aware passages for military career references.
--
-- Additive only. It does NOT modify the existing reference tables
-- (mos_reference_enlisted, aoc_reference_officer, navy_rating_reference,
-- usmc_mos_reference, mil_reference_cache); their schemas are not tracked in
-- this repo. The app treats rows in those tables as "unverified" until they are
-- replaced by registry rows imported from a recorded, reviewed publication.
--
-- Run in the Supabase SQL editor. Safe to run more than once.

-- One row per publication (or chapter of one) that passages were extracted from.
create table if not exists public.reference_sources (
  id                 uuid primary key default gen_random_uuid(),
  branch             text not null,
  personnel_category text not null check (personnel_category in ('enlisted', 'warrant', 'officer')),
  publication_number text,                    -- e.g. 'DA PAM 600-25'
  title              text not null,
  chapter            text,                    -- e.g. 'Chapter 4 — MOS 42A'
  career_field       text,                    -- e.g. 'CMF 42'
  proponent          text,
  official_url       text not null check (official_url ~ '^https://'),

  publication_date   date,                    -- date printed on the document
  effective_date     date,                    -- when it took effect, if stated
  last_checked_at    timestamptz,             -- when someone last confirmed it is still current
  uploaded_at        timestamptz not null default now(),  -- when WE ingested it (not the publication date)

  checksum_sha256    text,                    -- of the exact file that was extracted
  ingestion_status   text not null default 'pending' check (ingestion_status in ('pending', 'extracted', 'failed')),
  review_status      text not null default 'unreviewed' check (review_status in ('unreviewed', 'approved', 'rejected')),
  reviewed_by        text,
  reviewed_at        timestamptz,
  superseded_by      uuid references public.reference_sources (id),  -- newer approved source replacing this one
  notes              text                     -- conflicts, access limits, caveats
);

create index if not exists reference_sources_lookup_idx
  on public.reference_sources (branch, personnel_category, review_status);

-- Extracted passages, one per section, with exact page and rank provenance.
create table if not exists public.reference_passages (
  id                 uuid primary key default gen_random_uuid(),
  source_id          uuid not null references public.reference_sources (id) on delete cascade,
  branch             text not null,
  personnel_category text not null check (personnel_category in ('enlisted', 'warrant', 'officer')),
  occupation_code    text not null,           -- exact code, upper-case, no spaces
  occupation_title   text,

  section_type       text not null check (section_type in ('general_duties', 'rank_duties', 'training', 'credentials', 'assignments')),
  -- NULL = applies to every grade. Otherwise 'E-6', 'E-1..E-4', or a comma list 'E-5,E-6'.
  rank_band          text,
  heading            text,                    -- section heading as printed, e.g. 'Staff Sergeant'
  body               text not null,

  pdf_page_start     integer,                 -- PDF page INDEX, not the printed page number
  pdf_page_end       integer,
  printed_page       text,
  sort_order         integer not null default 0
);

create index if not exists reference_passages_lookup_idx
  on public.reference_passages (branch, personnel_category, occupation_code);
create index if not exists reference_passages_source_idx
  on public.reference_passages (source_id);

-- Historical specialty codes. The person's own past code is never overwritten;
-- this only tells the app which current reference to show, and why.
create table if not exists public.reference_code_aliases (
  id                 uuid primary key default gen_random_uuid(),
  branch             text not null,
  personnel_category text not null check (personnel_category in ('enlisted', 'warrant', 'officer')),
  historical_code    text not null,
  current_code       text not null,
  effective_from     date,
  effective_to       date,
  source_id          uuid references public.reference_sources (id),
  note               text,
  unique (branch, personnel_category, historical_code)
);

-- Access: these hold public-domain publications, so approved content is world-
-- readable; only the service role (the import tool) can write.
alter table public.reference_sources      enable row level security;
alter table public.reference_passages     enable row level security;
alter table public.reference_code_aliases enable row level security;

drop policy if exists "approved sources are public" on public.reference_sources;
create policy "approved sources are public" on public.reference_sources
  for select using (review_status = 'approved');

drop policy if exists "passages of approved sources are public" on public.reference_passages;
create policy "passages of approved sources are public" on public.reference_passages
  for select using (exists (
    select 1 from public.reference_sources s
    where s.id = reference_passages.source_id and s.review_status = 'approved'
  ));

drop policy if exists "aliases are public" on public.reference_code_aliases;
create policy "aliases are public" on public.reference_code_aliases
  for select using (true);


-- ===== supabase/migrations/005_reference_components_and_sections.sql =====
-- Follow-up to 004. Adds component-specific passages (Active / Reserve / Guard),
-- the section types the real Army career guides use, and content checksums.
--
-- Written as 005 (not an edit of 004) so it is correct whether or not 004 has
-- already been run. Safe to run more than once. Additive: no data is deleted.

-- Which components a passage applies to. NULL = every component. Otherwise a
-- comma list of: active, reserve, guard   e.g. 'reserve,guard'.
alter table public.reference_passages
  add column if not exists components text;

alter table public.reference_passages
  drop constraint if exists reference_passages_components_check;
alter table public.reference_passages
  add constraint reference_passages_components_check
  check (components is null or components ~ '^(active|reserve|guard)(,(active|reserve|guard))*$');

-- Section types, matching how the source documents are actually organised.
-- promotion_criteria is stored for completeness but is never sent to a model
-- or shown in a translation (it describes board selection, not the work).
alter table public.reference_passages
  drop constraint if exists reference_passages_section_type_check;
alter table public.reference_passages
  add constraint reference_passages_section_type_check
  check (section_type in (
    'general_duties',      -- what the specialty does (all grades)
    'rank_duties',         -- what is expected at a grade
    'assignments',         -- operational / generating / broadening / key developmental
    'training',            -- institutional training, PME, functional courses, education
    'lifelong_learning',
    'self_development',
    'credentials',         -- recommended civilian credentials/certifications
    'development',         -- general career-development guidance
    'prerequisites',
    'promotion_criteria',
    'grades_authorized'    -- added with 007; listed here too so re-running 005 after 007 never rejects existing rows
  ));

-- Where in the document this came from, and a fingerprint for review diffs.
alter table public.reference_passages
  add column if not exists chapter text,            -- e.g. 'Chapter 4. MOS 42A'
  add column if not exists body_sha256 text;

-- How the text was extracted (so a re-import with a newer tool is visible).
alter table public.reference_sources
  add column if not exists extraction_tool text,
  add column if not exists import_batch text;

create index if not exists reference_passages_components_idx
  on public.reference_passages (branch, personnel_category, occupation_code, components);


-- ===== supabase/migrations/006_reference_content_review.sql =====
-- An extraction is versioned separately from its source PDF: rank/component
-- mappings and parser corrections can change while the PDF checksum stays fixed.
alter table public.reference_sources
  add column if not exists content_sha256 text;

comment on column public.reference_sources.content_sha256 is
  'SHA-256 of the imported source metadata and passages. Approval SQL targets this exact extraction; cache keys include it.';

-- Existing approvals lack an extraction fingerprint. Review the newly generated
-- imports before approving again; never silently bless a pre-migration mapping.
update public.reference_sources
set review_status = 'unreviewed', reviewed_by = null, reviewed_at = null
where content_sha256 is null and review_status = 'approved';


-- ===== supabase/migrations/007_reference_passage_versions.sql =====
-- Passage-level effective dates and skill-level structure for DA PAM 611-21.
--
-- A specification can change mid-edition ("(Effective 202610)"), so a passage carries its own effective window.
-- Enlisted skill levels can say "performs the duties of the preceding skill level"; `cumulative` keeps that
-- relationship so retrieval can include the lower levels.

alter table public.reference_passages add column if not exists effective_from date;
alter table public.reference_passages add column if not exists effective_to   date;
alter table public.reference_passages add column if not exists cumulative     boolean not null default false;
alter table public.reference_passages add column if not exists skill_level    smallint;

comment on column public.reference_passages.effective_from is 'First day this passage applies (from a dated marker such as "Effective 202610"); null = no stated start.';
comment on column public.reference_passages.effective_to   is 'Day this passage stops applying (the next version takes over); null = still in force.';
comment on column public.reference_passages.cumulative     is 'True when the passage says the grade also performs the duties of the lower level(s).';

alter table public.reference_passages drop constraint if exists reference_passages_section_type_check;
alter table public.reference_passages
  add constraint reference_passages_section_type_check
  check (section_type in (
    'general_duties', 'rank_duties', 'assignments', 'training', 'lifelong_learning', 'self_development',
    'credentials', 'development', 'prerequisites', 'promotion_criteria',
    'grades_authorized'    -- officer AOCs: grades the AOC is authorized at / special grading of positions
  ));


-- ===== import: army-611-21-enlisted-ch10c =====
