  ('a4fea0ad-c531-5dff-829d-815a3058365e', 'a6b40ab7-9883-5645-a496-0e2393fba45b', 'Army', 'officer', '36A', 'Finance and Comptroller Officer', 'assignments', 'O-5', 'reserve', 'Field Grade — Broadening assignments for lieutenant colonels (see Fig 3)', '5. Finance and Comptroller Reserve Component (RC) Officer Development', '(a) Nominative (Joint/HRC/DA/OSD) Position
(b) USARC/OCAR Analyst
(c) Branch Chief
(d) Integration Officer
(e) Inspector General
(f) Legislative Liaison Officer (LNO)
(g) Plans Officer', '511152660e5d2208ee46ae7440f56f4792686eda7b5ff65ddab2048b91509b2c', 11, 11, '11', 44, null, null, false, null),
  ('86cb96de-651a-5ce3-880a-3f1a73e0f046', 'a6b40ab7-9883-5645-a496-0e2393fba45b', 'Army', 'officer', '36A', 'Finance and Comptroller Officer', 'assignments', 'O-6', 'reserve', 'Field Grade — Key Developmental assignments for colonels (see Fig 3)', '5. Finance and Comptroller Reserve Component (RC) Officer Development', '(a) Brigade Command (90A/01A)
